// Idempotent command ledger.
//
// A command id is generated by the client and reused verbatim on any retry.
// The first request records it durably and returns a receipt; every later
// request with the same id and payload returns the same receipt without
// executing anything again. The same id with a different payload is refused.

import { createHash } from "node:crypto";
import { canonicalJson, validateCommand, type CommandKind, type CommandReceipt, type CommandRequest, type CommandState } from "../protocol.ts";
import { integer, optionalText, text, type Database, type Row } from "./db.ts";
import type { EventJournal } from "./events.ts";

export const TERMINAL: readonly CommandState[] = ["completed", "failed", "rejected", "cancelled", "uncertain"];

export function payloadHash(request: Pick<CommandRequest, "kind" | "sessionID" | "directory" | "payload">): string {
  return createHash("sha256").update(canonicalJson({ kind: request.kind, sessionID: request.sessionID, directory: request.directory, payload: request.payload })).digest("hex");
}

const KINDS: readonly CommandKind[] = ["prompt", "steer", "abort", "compact", "model.set", "model.transition"];
const STATES: readonly CommandState[] = ["accepted", "dispatching", "running", "completed", "failed", "rejected", "cancelled", "uncertain"];

function member<T extends string>(values: readonly T[], value: string, field: string): T {
  const found = values.find((candidate) => candidate === value);
  if (!found) throw new Error(`Corrupt command ledger ${field}: ${value.slice(0, 40)}`);
  return found;
}

function receiptOf(row: Row): CommandReceipt {
  return {
    id: text(row, "id"),
    kind: member(KINDS, text(row, "kind"), "kind"),
    sessionID: text(row, "session_id"),
    state: member(STATES, text(row, "state"), "state"),
    entryId: optionalText(row, "entry_id"),
    error: optionalText(row, "error"),
    createdAt: integer(row, "created"),
    updatedAt: integer(row, "updated"),
  };
}

export type BeginResult =
  | { kind: "new"; receipt: CommandReceipt }
  | { kind: "duplicate"; receipt: CommandReceipt }
  | { kind: "conflict" };

export class CommandLedger {
  constructor(private readonly db: Database, private readonly journal: EventJournal) {}

  get(id: string): CommandReceipt | null {
    const row = this.db.get("SELECT * FROM commands WHERE id=?", id);
    return row ? receiptOf(row) : null;
  }

  /** Complete durable input. Schema-1 rows honestly have no recoverable input. */
  getRequest(id: string): CommandRequest | null {
    const row = this.db.get("SELECT * FROM commands WHERE id=?", id);
    const payload = optionalText(row, "payload");
    if (!row || payload === null) return null;
    const request = validateCommand({
      id: text(row, "id"), kind: text(row, "kind"), sessionID: text(row, "session_id"),
      directory: text(row, "directory"), payload: JSON.parse(payload),
    });
    if (typeof request === "string") throw new Error(`Corrupt command ledger input for ${id}`);
    return request;
  }

  begin(request: CommandRequest, source?: { source?: string; sourceId?: string | null }): BeginResult {
    const hash = payloadHash(request);
    return this.db.transaction((): BeginResult => {
      const existing = this.db.get("SELECT * FROM commands WHERE id=?", request.id);
      if (existing) {
        if (text(existing, "payload_hash") !== hash) return { kind: "conflict" };
        return { kind: "duplicate", receipt: { ...receiptOf(existing), duplicate: true } };
      }
      const now = Date.now();
      this.db.run("INSERT INTO commands(id,kind,session_id,directory,payload_hash,payload,state,source,source_id,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
        request.id, request.kind, request.sessionID, request.directory, hash, canonicalJson(request.payload), "accepted", source?.source ?? null, source?.sourceId ?? null, now, now);
      const receipt = receiptOf(this.db.get("SELECT * FROM commands WHERE id=?", request.id)!);
      this.publish(request.directory, receipt);
      return { kind: "new", receipt };
    });
  }

  /** Monotonic transitions only; a terminal receipt is never reopened. */
  update(id: string, state: CommandState, patch: { entryId?: string | null; error?: string | null } = {}): CommandReceipt | null {
    return this.db.transaction(() => {
      const row = this.db.get("SELECT * FROM commands WHERE id=?", id);
      if (!row) return null;
      const current = member(STATES, text(row, "state"), "state");
      if (TERMINAL.includes(current) && current !== state) return receiptOf(row);
      this.db.run("UPDATE commands SET state=?, entry_id=COALESCE(?,entry_id), error=COALESCE(?,error), updated=? WHERE id=?",
        state, patch.entryId ?? null, patch.error?.slice(0, 2000) ?? null, Date.now(), id);
      const receipt = receiptOf(this.db.get("SELECT * FROM commands WHERE id=?", id)!);
      this.publish(text(row, "directory"), receipt);
      return receipt;
    });
  }

  /** The executed command of a session that a newly appended user entry belongs to. */
  awaitingEntry(sessionID: string): string | null {
    return optionalText(this.db.get("SELECT id FROM commands WHERE session_id=? AND kind IN ('prompt','steer') AND entry_id IS NULL AND state IN ('dispatching','running','completed','failed') ORDER BY created LIMIT 1", sessionID), "id");
  }

  /** The durable user entry id is attached once, even to a finished receipt. */
  recordEntry(id: string, entryId: string): void {
    this.db.transaction(() => {
      const row = this.db.get("SELECT * FROM commands WHERE id=? AND entry_id IS NULL", id);
      if (!row) return;
      this.db.run("UPDATE commands SET entry_id=?, updated=? WHERE id=?", entryId, Date.now(), id);
      this.publish(text(row, "directory"), receiptOf(this.db.get("SELECT * FROM commands WHERE id=?", id)!));
    });
  }

  /** Commands still open for one session, oldest first. */
  open(sessionID: string): CommandReceipt[] {
    return this.db.all("SELECT * FROM commands WHERE session_id=? AND state IN ('accepted','dispatching','running') ORDER BY created", sessionID).map(receiptOf);
  }

  /**
   * After a crash: work that never reached the SDK is cancelled (provably not
   * executed); work that may have executed becomes "uncertain". Nothing is
   * replayed automatically.
   */
  recoverAfterRestart(): { cancelled: CommandReceipt[]; uncertain: CommandReceipt[] } {
    const cancelled = this.db.all("SELECT * FROM commands WHERE state='accepted'").map(receiptOf);
    const uncertain = this.db.all("SELECT * FROM commands WHERE state IN ('dispatching','running')").map(receiptOf);
    for (const receipt of cancelled) this.update(receipt.id, "cancelled", { error: "Enki Runtime перезапустилась до выполнения. Запрос не выполнялся." });
    for (const receipt of uncertain) this.update(receipt.id, "uncertain", { error: "Enki Runtime остановилась во время выполнения. Результат не подтверждён; повторной отправки не было." });
    return { cancelled, uncertain };
  }

  private publish(directory: string, receipt: CommandReceipt): void {
    this.journal.append(directory, receipt.sessionID, { type: "command.updated", properties: { receipt } });
  }
}
